, \'jackets\', 3500000 , 1547 , 0.103 , 0.548 Union all Select \'Marketplace\', \'snitch\', \'jeans\', 59532410 , 36207 , 0.1 , 0.569 Union all Select \'Marketplace\', \'snitch\', \'joggers & trackpants\', 1422750 , 981 , 0.129 , 0.479 Union all Select \'Marketplace\', \'snitch\', \'overshirt\', 7703764 , 6654 , 0.05 , 0.489 Union all Select \'Marketplace\', \'snitch\', \'pyjamas\', 9029 , 14 , 0.06 , 0.638 Union all Select \'Marketplace\', \'snitch\', \'shirts\', 124259625 , 125854 , 0.196 , 0.55 Union all Select \'Marketplace\', \'snitch\', \'shorts\', 7000000 , 6093 , 0.15 , 0.587 Union all Select \'Marketplace\', \'snitch\', \'sweaters\', 2625000 , 2217 , 0.3 , 0.49 Union all Select \'Marketplace\', \'snitch\', \'sweatshirts\', 875000 , 768 , 0.35 , 0.516 Union all Select \'Marketplace\', \'snitch\', \'trousers\', 43275975 , 33549 , 0.229 , 0.496 Union all Select \'Marketplace\', \'snitch\', \'tshirts\', 44825560 , 48442 , 0.195 , 0.564 ) ,base_sales_2 AS ( SELECT date, UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'Marketplace\' WHEN type = \'Store\' THEN \'Offline\' END AS channel, \'B2C\' mode, SUM(gross_quantity::INT) AS qty, SUM(gross_sales::INT) AS gross_sales_value, FROM snitch_db.maplemonk.horizontal_sales_categories WHERE date >= \'2026-03-01\' and date < \'2026-04-01\' GROUP BY 1,2,3,4 ), mrp_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(sku, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(sku, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(sku, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, avg(MRP) MRP FROM snitch_db.maplemonk.logic_final_item_master WHERE BRAND = \'SNITCH\' Group by 1 ), mp_sor as ( SELECT TO_DATE(order_created_date, \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(style_, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(style_, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(style_, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(style_, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, \'Marketplace\' AS channel, \'SOR\' AS mode, SUM(TRY_TO_NUMBER(REPLACE(sales, \',\', \'\'))) AS qty, SUM(TRY_TO_NUMBER(REPLACE(revenue, \',\', \'\'))) AS gross_sales_value FROM snitch_db.maplemonk.mp_sor_sales_myntra WHERE order_created_date>=20260301 and order_created_date<=20260331 GROUP BY 1,2,3,4 UNION ALL SELECT TO_DATE(order_date_key, \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(style_, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(style_, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(style_, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(style_, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, \'Marketplace\' AS channel, \'SOR\' AS mode, SUM(TRY_TO_NUMBER(REPLACE(units, \',\', \'\'))) AS qty, SUM( TRY_TO_NUMBER(REPLACE(sp_per_unit_, \',\', \'\')) * TRY_TO_NUMBER(REPLACE(units, \',\', \'\')) ) AS gross_sales_value FROM snitch_db.maplemonk.mp_sor_sales_flipkart WHERE order_date_key>=20260301 and order_date_key<=20260331 GROUP BY 1,2,3,4 ) , base_sales as (select * from base_sales_2 union all select * from mp_sor) , meta_map as (select UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END ), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END ), MIN(a.category) ) AS category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END ), MIN(a.meta1) ) AS meta1, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END ), MIN(a.meta2) ) AS meta2, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END ), MIN(a.meta3) ) AS meta3, max(cogs) cogs from snitch_db.maplemonk.meta_mapping_cogs_sku a group by 1) select date,sku_group_clean sku_group,channel,mode,l1_category,category,meta1,meta2,meta3,bs.qty qty_sold,cogs,MRP,gross_sales_value revenue_generated, a.revenue revenue_target,a.qty qty_target, a.discount discount_prec_target, a.gm gm_perc_target, bs.qty*cogs cogs_value, bs.qty*MRP MRP_value, a.revenue*day(current_date())/31 revenue_target_till_date, a.qty*day(current_date())/31 qty_target_till_date FROM base_sales bs LEFT JOIN mrp_map mrp USING (sku_group_clean) LEFT JOIN meta_map mm USING (sku_group_clean) full outer join a using(l1_category,category,channel);",
